-- Tighten room-scoped Lucky Bag visibility, live room presence checks, and mic-seat realtime access.
drop policy if exists "active lucky bags visible" on public.talkzy_lucky_bags;
create policy "active lucky bags visible" on public.talkzy_lucky_bags for select to authenticated using ((status='active' and (scope='world' or exists (select 1 from public.talkzy_room_presence p where p.room_id=talkzy_lucky_bags.room_id and p.user_id=(select auth.uid()) and p.last_seen_at>now()-interval '75 seconds'))) or sender_id=(select auth.uid()) or exists (select 1 from public.talkzy_lucky_bag_claims c where c.bag_id=talkzy_lucky_bags.id and c.claimer_id=(select auth.uid()));
create or replace function public.talkzy_lucky_bag_claim(p_bag_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid:=auth.uid(); b public.talkzy_lucky_bags; reward bigint; bal bigint;
begin if u is null then raise exception 'Login required'; end if;
 select * into b from public.talkzy_lucky_bags where id=p_bag_id for update;
 if not found then raise exception 'Bag not found'; end if;
 if b.status<>'active' then raise exception 'Bag is no longer active'; end if;
 if b.expires_at<=now() then if b.remaining_coins>0 then insert into public.talkzy_wallets(user_id,balance) values(b.sender_id,0) on conflict do nothing; update public.talkzy_wallets set balance=balance+b.remaining_coins,updated_at=now() where user_id=b.sender_id returning balance into bal; insert into public.talkzy_coin_ledger(user_id,amount,balance_after,event_type,reference_id,note) values(b.sender_id,b.remaining_coins,bal,'lucky_bag_refund',b.id,'Expired Lucky Bag refund'); end if; update public.talkzy_lucky_bags set remaining_coins=0,remaining_bags=0,status='expired',closed_at=now() where id=b.id; return jsonb_build_object('expired',true,'message','Expired Lucky Bag has been refunded'); end if;
 if b.sender_id=u then raise exception 'Cannot open your own bag'; end if;
 if b.remaining_bags<=0 or b.remaining_coins<=0 then raise exception 'Bag empty'; end if;
 if b.scope='room' and not exists(select 1 from public.talkzy_room_presence p where p.room_id=b.room_id and p.user_id=u and p.last_seen_at>now()-interval '75 seconds') then raise exception 'Enter sender room first'; end if;
 if exists(select 1 from public.talkzy_lucky_bag_claims where bag_id=p_bag_id and claimer_id=u) then raise exception 'Already claimed'; end if;
 if b.remaining_bags=1 then reward:=b.remaining_coins; else reward:=1+floor(random()*(b.remaining_coins-b.remaining_bags+1))::bigint; end if;
 update public.talkzy_lucky_bags set remaining_coins=remaining_coins-reward,remaining_bags=remaining_bags-1,status=case when remaining_bags-1=0 then 'claimed' else 'active' end,closed_at=case when remaining_bags-1=0 then now() else null end where id=p_bag_id;
 insert into public.talkzy_lucky_bag_claims(bag_id,claimer_id,reward_coins) values(p_bag_id,u,reward);
 insert into public.talkzy_wallets(user_id,balance) values(u,0) on conflict do nothing;
 update public.talkzy_wallets set balance=balance+reward,updated_at=now() where user_id=u returning balance into bal;
 insert into public.talkzy_coin_ledger(user_id,amount,balance_after,event_type,reference_id,note) values(u,reward,bal,'lucky_bag_claim',p_bag_id,'Lucky Bag reward');
 return jsonb_build_object('bag_id',p_bag_id,'reward_coins',reward,'balance',bal); end $$;
revoke all on function public.talkzy_lucky_bag_claim(uuid) from public,anon;
grant execute on function public.talkzy_lucky_bag_claim(uuid) to authenticated;
drop policy if exists "Room participants can view microphone seats" on public.talkzy_room_mic_seats;
create policy "Room participants can view microphone seats" on public.talkzy_room_mic_seats for select to authenticated using (exists (select 1 from public.talkzy_rooms r where r.id=talkzy_room_mic_seats.room_id and r.status='active' and r.owner_id=(select auth.uid())) or exists (select 1 from public.talkzy_room_members m join public.talkzy_rooms r on r.id=m.room_id where m.room_id=talkzy_room_mic_seats.room_id and m.user_id=(select auth.uid()) and r.status='active') or exists (select 1 from public.talkzy_room_admins a join public.talkzy_rooms r on r.id=a.room_id where a.room_id=talkzy_room_mic_seats.room_id and a.user_id=(select auth.uid()) and r.status='active') or exists (select 1 from public.talkzy_room_visitors v join public.talkzy_rooms r on r.id=v.room_id where v.room_id=talkzy_room_mic_seats.room_id and v.user_id=(select auth.uid()) and v.last_seen_at>now()-interval '5 minutes' and r.status='active'));
drop policy if exists "room participants and visitors can read room approval settings" on public.talkzy_room_settings;
create policy "room participants and visitors can read room approval settings" on public.talkzy_room_settings for select to authenticated using (exists (select 1 from public.talkzy_rooms r where r.id=talkzy_room_settings.room_id and r.status='active' and (r.owner_id=(select auth.uid()) or exists (select 1 from public.talkzy_room_members m where m.room_id=r.id and m.user_id=(select auth.uid())) or exists (select 1 from public.talkzy_room_visitors v where v.room_id=r.id and v.user_id=(select auth.uid()) and v.last_seen_at>now()-interval '5 minutes'))));
drop policy if exists "Room participants can read mic controls" on public.talkzy_room_mic_controls;
create policy "Room participants can read mic controls" on public.talkzy_room_mic_controls for select to authenticated using (exists (select 1 from public.talkzy_rooms r where r.id=talkzy_room_mic_controls.room_id and r.status='active' and r.owner_id=(select auth.uid())) or exists (select 1 from public.talkzy_room_presence p join public.talkzy_rooms r on r.id=p.room_id where p.room_id=talkzy_room_mic_controls.room_id and p.user_id=(select auth.uid()) and p.last_seen_at>now()-interval '75 seconds' and r.status='active'));
drop policy if exists "room participants and visitors can read room messages" on public.talkzy_room_messages;
create policy "room participants and visitors can read room messages" on public.talkzy_room_messages for select to authenticated using (exists (select 1 from public.talkzy_rooms r where r.id=talkzy_room_messages.room_id and r.status='active' and (r.owner_id=(select auth.uid()) or exists (select 1 from public.talkzy_room_members m where m.room_id=r.id and m.user_id=(select auth.uid())) or exists (select 1 from public.talkzy_room_visitors v where v.room_id=r.id and v.user_id=(select auth.uid()) and v.last_seen_at>now()-interval '5 minutes'))) and not exists (select 1 from public.talkzy_room_chat_clears c where c.room_id=talkzy_room_messages.room_id and c.user_id=(select auth.uid()) and c.cleared_at>=talkzy_room_messages.created_at));